fn find_max(numbers: &[i32]) -> Option<i32> {
    if numbers.is_empty() {
        return None;
    }
    let mut max = numbers[0];
    for &number in numbers.iter().skip(1) {
        if number > max {
            max = number;
        }
    }
    Some(max)
}

